#include <ctype.h>
#include <errno.h>
#include <limits.h>
#include <math.h>
#include <stddef.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef enum tipo_param : int {
    TIPO_INT = 0, TIPO_DOUBLE = 1, TIPO_BOOL = 2
} tipo_param_t;

typedef struct voce_reg {
    char nome[16];
    tipo_param_t tipo;
    void *ptr;
} voce_reg_t;

const void *elemento_generico(const void *base, size_t idx, size_t dim_elem);
void stampa_parametro(const voce_reg_t *v);
bool aggiorna_parametro(voce_reg_t *v, const char *val_str);
voce_reg_t *cerca_voce(voce_reg_t reg[], size_t n, const char *nome);

int main(void) {
    int contatori[3] = {10, 20, 30};
    double soglie[2] = {1.5, 9.25};
    bool attivo = false;
    voce_reg_t reg[6] = {
        {"c0", TIPO_INT, &contatori[0]}, {"c1", TIPO_INT, &contatori[1]},
        {"c2", TIPO_INT, &contatori[2]}, {"s0", TIPO_DOUBLE, &soglie[0]},
        {"s1", TIPO_DOUBLE, &soglie[1]}, {"attivo", TIPO_BOOL, &attivo}
    };
    bool indirizzi_ok = true;
    for (size_t i = 0; i < 3; ++i) {
        if (elemento_generico(contatori, i, sizeof(int)) != &contatori[i]) { indirizzi_ok = false; }
    }
    for (size_t i = 0; i < 2; ++i) {
        if (elemento_generico(soglie, i, sizeof(double)) != &soglie[i]) { indirizzi_ok = false; }
    }
    char riga[128], cmd[16], nome[32], val[64], extra = '\0';
    while (fgets(riga, (int)sizeof(riga), stdin) != nullptr) {
        if (sscanf(riga, "%15s", cmd) != 1) { continue; }
        if (strcmp(cmd, "GET") == 0 && sscanf(riga, "GET %31s %c", nome, &extra) == 1) {
            voce_reg_t *v = cerca_voce(reg, 6, nome);
            if (v == nullptr) { printf("Parametro sconosciuto: %s\n", nome); }
            else { stampa_parametro(v); }
        } else if (strcmp(cmd, "SET") == 0 && sscanf(riga, "SET %31s %63s %c", nome, val, &extra) == 2) {
            voce_reg_t *v = cerca_voce(reg, 6, nome);
            if (v == nullptr) { printf("Parametro sconosciuto: %s\n", nome); }
            else if (!aggiorna_parametro(v, val)) { printf("Valore non valido per %s\n", nome); }
        } else {
            fprintf(stderr, "Errore: comando non valido.\n");
            return EXIT_FAILURE;
        }
    }
    printf("Stato finale:\n");
    for (size_t i = 0; i < 6; ++i) { stampa_parametro(&reg[i]); }
    printf("Verifica indirizzi a byte: %s\n", indirizzi_ok ? "OK" : "ERRORE");
    return EXIT_SUCCESS;
}

const void *elemento_generico(const void *base, size_t idx, size_t dim_elem) {
    const unsigned char *bytes = base;
    return bytes + idx * dim_elem;
}

void stampa_parametro(const voce_reg_t *v) {
    const void *p = v->ptr;
    if (v->tipo == TIPO_INT) {
        const int *pi = p;
        printf("%s (int) = %d\n", v->nome, *pi);
    } else if (v->tipo == TIPO_DOUBLE) {
        const double *pd = p;
        printf("%s (double) = %.2f\n", v->nome, *pd);
    } else {
        const bool *pb = p;
        printf("%s (bool) = %s\n", v->nome, *pb ? "true" : "false");
    }
}

bool aggiorna_parametro(voce_reg_t *v, const char *val_str) {
    if (v == nullptr || val_str == nullptr || *val_str == '\0' || isspace((unsigned char)*val_str)) {
        return false;
    }
    char *end = nullptr;
    errno = 0;
    if (v->tipo == TIPO_INT) {
        long x = strtol(val_str, &end, 10);
        if (end == val_str || *end != '\0' || errno == ERANGE || x < INT_MIN || x > INT_MAX) {
            return false;
        }
        int *pi = v->ptr;
        *pi = (int)x;
        return true;
    }
    if (v->tipo == TIPO_DOUBLE) {
        double d = strtod(val_str, &end);
        if (end == val_str || *end != '\0' || errno == ERANGE || d != d || fabs(d) == HUGE_VAL) {
            return false;
        }
        double *pd = v->ptr;
        *pd = d;
        return true;
    }
    if (strcmp(val_str, "0") == 0 || strcmp(val_str, "1") == 0) {
        bool *pb = v->ptr;
        *pb = (val_str[0] == '1');
        return true;
    }
    return false;
}

voce_reg_t *cerca_voce(voce_reg_t reg[], size_t n, const char *nome) {
    for (size_t i = 0; i < n; ++i) {
        if (strcmp(reg[i].nome, nome) == 0) { return &reg[i]; }
    }
    return nullptr;
}

#include <inttypes.h>
#include <stddef.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

constexpr size_t CAP_BUF = 64;

typedef struct buf_bin {
    uint8_t dati[CAP_BUF];
    size_t len;
} buf_bin_t;

bool buf_inserisci(buf_bin_t *b, size_t pos, const uint8_t *src, size_t n);
bool buf_rimuovi(buf_bin_t *b, size_t pos, size_t n);
bool buf_riempi(buf_bin_t *b, size_t pos, size_t n, uint8_t val);
ptrdiff_t buf_trova_byte(const buf_bin_t *b, size_t da, uint8_t val);
int buf_confronta(const buf_bin_t *b, size_t p1, size_t p2, size_t n, bool *ok);

int main(void) {
    buf_bin_t b = {};
    char riga[256], cmd[16], extra = '\0';
    while (fgets(riga, (int)sizeof(riga), stdin) != nullptr) {
        if (sscanf(riga, "%15s", cmd) != 1) { continue; }
        if (strcmp(cmd, "INS") == 0) {
            size_t pos = 0, k = 0;
            int letti = 0;
            if (sscanf(riga, "INS %zu %zu%n", &pos, &k, &letti) != 2 || k > 16) {
                fprintf(stderr, "Errore: comando INS non valido.\n");
                return EXIT_FAILURE;
            }
            uint8_t tmp[16] = {};
            const char *p = riga + letti;
            for (size_t i = 0; i < k; ++i) {
                unsigned int v = 0;
                int step = 0;
                if (sscanf(p, "%u%n", &v, &step) != 1 || v > UINT8_MAX) {
                    fprintf(stderr, "Errore: byte INS non valido.\n");
                    return EXIT_FAILURE;
                }
                tmp[i] = (uint8_t)v;
                p += step;
            }
            if (sscanf(p, " %c", &extra) == 1) { return EXIT_FAILURE; }
            if (buf_inserisci(&b, pos, tmp, k)) { printf("INS ok (len=%zu)\n", b.len); }
            else { printf("INS rifiutato\n"); }
        } else if (strcmp(cmd, "DEL") == 0) {
            size_t pos = 0, n = 0;
            if (sscanf(riga, "DEL %zu %zu %c", &pos, &n, &extra) != 2) { return EXIT_FAILURE; }
            if (buf_rimuovi(&b, pos, n)) { printf("DEL ok (len=%zu)\n", b.len); }
            else { printf("DEL rifiutato\n"); }
        } else if (strcmp(cmd, "FILL") == 0) {
            size_t pos = 0, n = 0;
            unsigned int val = 0;
            if (sscanf(riga, "FILL %zu %zu %u %c", &pos, &n, &val, &extra) != 3 || val > UINT8_MAX) {
                return EXIT_FAILURE;
            }
            if (buf_riempi(&b, pos, n, (uint8_t)val)) { printf("FILL ok\n"); }
            else { printf("FILL rifiutato\n"); }
        } else if (strcmp(cmd, "FIND") == 0) {
            size_t da = 0;
            unsigned int val = 0;
            if (sscanf(riga, "FIND %zu %u %c", &da, &val, &extra) != 2 || val > UINT8_MAX) {
                return EXIT_FAILURE;
            }
            printf("FIND -> %td\n", buf_trova_byte(&b, da, (uint8_t)val));
        } else if (strcmp(cmd, "CMP") == 0) {
            size_t p1 = 0, p2 = 0, n = 0;
            bool ok = false;
            if (sscanf(riga, "CMP %zu %zu %zu %c", &p1, &p2, &n, &extra) != 3) { return EXIT_FAILURE; }
            int r = buf_confronta(&b, p1, p2, n, &ok);
            if (ok) { printf("CMP -> %d\n", r); }
            else { printf("CMP rifiutato\n"); }
        } else if (strcmp(cmd, "DUMP") == 0 && sscanf(riga, "DUMP %c", &extra) != 1) {
            printf("DUMP (%zu):", b.len);
            if (b.len == 0) { printf(" (vuoto)\n"); }
            else {
                for (size_t i = 0; i < b.len; ++i) { printf(" %02" PRIx8, b.dati[i]); }
                printf("\n");
            }
        } else {
            fprintf(stderr, "Errore: comando sconosciuto.\n");
            return EXIT_FAILURE;
        }
    }
    return EXIT_SUCCESS;
}

bool buf_inserisci(buf_bin_t *b, size_t pos, const uint8_t *src, size_t n) {
    if (b == nullptr || pos > b->len || n > CAP_BUF - b->len) { return false; }
    if (n > 0) {
        if (pos < b->len) {
            memmove(b->dati + pos + n, b->dati + pos, b->len - pos);
        }
        memcpy(b->dati + pos, src, n);
        b->len += n;
    }
    return true;
}

bool buf_rimuovi(buf_bin_t *b, size_t pos, size_t n) {
    if (b == nullptr || pos > b->len || n > b->len - pos) { return false; }
    if (n > 0) {
        if (pos + n < b->len) {
            memmove(b->dati + pos, b->dati + pos + n, b->len - (pos + n));
        }
        b->len -= n;
    }
    return true;
}

bool buf_riempi(buf_bin_t *b, size_t pos, size_t n, uint8_t val) {
    if (b == nullptr || pos > b->len || n > b->len - pos) { return false; }
    if (n > 0) { memset(b->dati + pos, val, n); }
    return true;
}

ptrdiff_t buf_trova_byte(const buf_bin_t *b, size_t da, uint8_t val) {
    if (b == nullptr || da >= b->len) { return -1; }
    const void *trovato = memchr(b->dati + da, val, b->len - da);
    if (trovato == nullptr) { return -1; }
    return (const uint8_t *)trovato - b->dati;
}

int buf_confronta(const buf_bin_t *b, size_t p1, size_t p2, size_t n, bool *ok) {
    if (b == nullptr || ok == nullptr || n > b->len || p1 > b->len - n || p2 > b->len - n) {
        if (ok != nullptr) { *ok = false; }
        return 0;
    }
    *ok = true;
    if (n == 0) { return 0; }
    int r = memcmp(b->dati + p1, b->dati + p2, n);
    return (r < 0) ? -1 : (r > 0 ? 1 : 0);
}

#include <inttypes.h>
#include <stddef.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct vettore_gen {
    void *dati;
    size_t dim_elem;
    size_t len;
    size_t cap;
} vettore_gen_t;

typedef struct misura {
    int id;
    double valore;
} misura_t;

void vg_init(vettore_gen_t *v, size_t dim_elem);
void vg_free(vettore_gen_t *v);
bool vg_riserva(vettore_gen_t *v, size_t nuova_cap);
bool vg_inserisci(vettore_gen_t *v, size_t pos, const void *elem);
bool vg_rimuovi(vettore_gen_t *v, size_t pos, void *out);
const void *vg_leggi(const vettore_gen_t *v, size_t pos);
bool vg_scambia(vettore_gen_t *v, size_t i, size_t j);

int main(void) {
    vettore_gen_t v_num, v_mis;
    vg_init(&v_num, sizeof(int64_t));
    vg_init(&v_mis, sizeof(misura_t));
    char riga[128], cmd[16], extra = '\0';
    while (fgets(riga, (int)sizeof(riga), stdin) != nullptr) {
        if (sscanf(riga, "%15s", cmd) != 1) { continue; }
        size_t pos = 0, i = 0, j = 0;
        long long v64 = 0;
        int id = 0;
        double val = 0.0;
        if (strcmp(cmd, "NUM_INS") == 0 && sscanf(riga, "NUM_INS %zu %lld %c", &pos, &v64, &extra) == 2) {
            int64_t x = (int64_t)v64;
            if (!vg_inserisci(&v_num, pos, &x)) { printf("ERR\n"); }
        } else if (strcmp(cmd, "NUM_DEL") == 0 && sscanf(riga, "NUM_DEL %zu %c", &pos, &extra) == 1) {
            int64_t rim = 0;
            if (vg_rimuovi(&v_num, pos, &rim)) { printf("DEL_NUM: %" PRId64 "\n", rim); }
            else { printf("ERR\n"); }
        } else if (strcmp(cmd, "NUM_SWAP") == 0 && sscanf(riga, "NUM_SWAP %zu %zu %c", &i, &j, &extra) == 2) {
            if (!vg_scambia(&v_num, i, j)) { printf("ERR\n"); }
        } else if (strcmp(cmd, "MIS_INS") == 0 && sscanf(riga, "MIS_INS %zu %d %lf %c", &pos, &id, &val, &extra) == 3) {
            misura_t m = {.id = id, .valore = val};
            if (!vg_inserisci(&v_mis, pos, &m)) { printf("ERR\n"); }
        } else if (strcmp(cmd, "MIS_DEL") == 0 && sscanf(riga, "MIS_DEL %zu %c", &pos, &extra) == 1) {
            misura_t rim = {};
            if (vg_rimuovi(&v_mis, pos, &rim)) { printf("DEL_MIS: #%d=%.2f\n", rim.id, rim.valore); }
            else { printf("ERR\n"); }
        } else if (strcmp(cmd, "MIS_SWAP") == 0 && sscanf(riga, "MIS_SWAP %zu %zu %c", &i, &j, &extra) == 2) {
            if (!vg_scambia(&v_mis, i, j)) { printf("ERR\n"); }
        } else {
            vg_free(&v_num); vg_free(&v_mis);
            fprintf(stderr, "Errore: comando non valido.\n");
            return EXIT_FAILURE;
        }
    }
    printf("NUM (len=%zu, cap=%zu):", v_num.len, v_num.cap);
    if (v_num.len == 0) { printf(" (vuoto)\n"); }
    else {
        for (size_t k = 0; k < v_num.len; ++k) {
            const int64_t *p = vg_leggi(&v_num, k);
            printf(" %" PRId64, *p);
        }
        printf("\n");
    }
    printf("MIS (len=%zu, cap=%zu):", v_mis.len, v_mis.cap);
    if (v_mis.len == 0) { printf(" (vuoto)\n"); }
    else {
        for (size_t k = 0; k < v_mis.len; ++k) {
            const misura_t *m = vg_leggi(&v_mis, k);
            printf(" #%d=%.2f", m->id, m->valore);
        }
        printf("\n");
    }
    vg_free(&v_num);
    vg_free(&v_mis);
    return EXIT_SUCCESS;
}

void vg_init(vettore_gen_t *v, size_t dim_elem) {
    *v = (vettore_gen_t){.dati = nullptr, .dim_elem = dim_elem, .len = 0, .cap = 0};
}

void vg_free(vettore_gen_t *v) {
    if (v != nullptr) { free(v->dati); v->dati = nullptr; v->len = 0; v->cap = 0; }
}

bool vg_riserva(vettore_gen_t *v, size_t nuova_cap) {
    if (v == nullptr || v->dim_elem == 0 || nuova_cap <= v->cap) { return nuova_cap <= v->cap; }
    if (nuova_cap > SIZE_MAX / v->dim_elem) { return false; }
    void *tmp = realloc(v->dati, nuova_cap * v->dim_elem);
    if (tmp == nullptr) { return false; }
    v->dati = tmp;
    v->cap = nuova_cap;
    return true;
}

bool vg_inserisci(vettore_gen_t *v, size_t pos, const void *elem) {
    if (v == nullptr || elem == nullptr || pos > v->len) { return false; }
    if (v->len == v->cap) {
        size_t ncap = (v->cap == 0) ? 2 : (v->cap * 2);
        if (!vg_riserva(v, ncap)) { return false; }
    }
    unsigned char *base = v->dati;
    if (pos < v->len) {
        memmove(base + (pos + 1) * v->dim_elem, base + pos * v->dim_elem, (v->len - pos) * v->dim_elem);
    }
    memcpy(base + pos * v->dim_elem, elem, v->dim_elem);
    ++v->len;
    return true;
}

bool vg_rimuovi(vettore_gen_t *v, size_t pos, void *out) {
    if (v == nullptr || pos >= v->len) { return false; }
    unsigned char *base = v->dati;
    if (out != nullptr) { memcpy(out, base + pos * v->dim_elem, v->dim_elem); }
    if (pos + 1 < v->len) {
        memmove(base + pos * v->dim_elem, base + (pos + 1) * v->dim_elem, (v->len - pos - 1) * v->dim_elem);
    }
    --v->len;
    return true;
}

const void *vg_leggi(const vettore_gen_t *v, size_t pos) {
    if (v == nullptr || pos >= v->len) { return nullptr; }
    const unsigned char *base = v->dati;
    return base + pos * v->dim_elem;
}

bool vg_scambia(vettore_gen_t *v, size_t i, size_t j) {
    if (v == nullptr || i >= v->len || j >= v->len) { return false; }
    if (i == j) { return true; }
    void *tmp = malloc(v->dim_elem);
    if (tmp == nullptr) { return false; }
    unsigned char *base = v->dati;
    memcpy(tmp, base + i * v->dim_elem, v->dim_elem);
    memcpy(base + i * v->dim_elem, base + j * v->dim_elem, v->dim_elem);
    memcpy(base + j * v->dim_elem, tmp, v->dim_elem);
    free(tmp);
    return true;
}

#include <inttypes.h>
#include <math.h>
#include <stddef.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

double norma_i32(int32_t x) { return fabs((double)x); }
double norma_u32(uint32_t x) { return (double)x; }
double norma_dbl(double x) { return fabs(x); }
double norma_str(const char *s) { return (s == nullptr) ? 0.0 : (double)strlen(s); }
double norma_null(nullptr_t p) { (void)p; return 0.0; }
int32_t incrementa_cont(int *c, int32_t x) { ++(*c); return x; }

int main(void) {
    char riga[256], testo[32], extra = '\0';
    long long a_in = 0;
    unsigned long long b_in = 0;
    double c = 0.0;
    int flag_null = 0;
    if (fgets(riga, (int)sizeof(riga), stdin) == nullptr ||
        sscanf(riga, "%lld %llu %lf %31s %d %c", &a_in, &b_in, &c, testo, &flag_null, &extra) != 5 ||
        a_in < INT32_MIN || a_in > INT32_MAX || b_in > UINT32_MAX || (flag_null != 0 && flag_null != 1)) {
        fprintf(stderr, "Errore: input non valido.\n");
        return EXIT_FAILURE;
    }
    int32_t a = (int32_t)a_in;
    uint32_t b = (uint32_t)b_in;
    char *p_mut = (flag_null == 1) ? nullptr : testo;
    const char *p_const = "costante";
    nullptr_t np = nullptr;

    const char *t_a = _Generic(a, int32_t: "int32_t", uint32_t: "uint32_t", double: "double",
                               char *: "char *", const char *: "const char *", nullptr_t: "nullptr_t", default: "altro");
    const char *t_b = _Generic(b, int32_t: "int32_t", uint32_t: "uint32_t", double: "double",
                               char *: "char *", const char *: "const char *", nullptr_t: "nullptr_t", default: "altro");
    const char *t_c = _Generic(c, int32_t: "int32_t", uint32_t: "uint32_t", double: "double",
                               char *: "char *", const char *: "const char *", nullptr_t: "nullptr_t", default: "altro");
    const char *t_pm = _Generic(p_mut, int32_t: "int32_t", uint32_t: "uint32_t", double: "double",
                                char *: "char *", const char *: "const char *", nullptr_t: "nullptr_t", default: "altro");
    const char *t_pc = _Generic(p_const, int32_t: "int32_t", uint32_t: "uint32_t", double: "double",
                                char *: "char *", const char *: "const char *", nullptr_t: "nullptr_t", default: "altro");
    const char *t_np = _Generic(np, int32_t: "int32_t", uint32_t: "uint32_t", double: "double",
                                char *: "char *", const char *: "const char *", nullptr_t: "nullptr_t", default: "altro");

    double n_a = _Generic(a, int32_t: norma_i32, uint32_t: norma_u32, double: norma_dbl, char *: norma_str, const char *: norma_str, nullptr_t: norma_null)(a);
    double n_b = _Generic(b, int32_t: norma_i32, uint32_t: norma_u32, double: norma_dbl, char *: norma_str, const char *: norma_str, nullptr_t: norma_null)(b);
    double n_c = _Generic(c, int32_t: norma_i32, uint32_t: norma_u32, double: norma_dbl, char *: norma_str, const char *: norma_str, nullptr_t: norma_null)(c);
    double n_pm = _Generic(p_mut, int32_t: norma_i32, uint32_t: norma_u32, double: norma_dbl, char *: norma_str, const char *: norma_str, nullptr_t: norma_null)(p_mut);
    double n_pc = _Generic(p_const, int32_t: norma_i32, uint32_t: norma_u32, double: norma_dbl, char *: norma_str, const char *: norma_str, nullptr_t: norma_null)(p_const);
    double n_np = _Generic(np, int32_t: norma_i32, uint32_t: norma_u32, double: norma_dbl, char *: norma_str, const char *: norma_str, nullptr_t: norma_null)(np);

    int chiamate = 0;
    const char *t_check = _Generic(incrementa_cont(&chiamate, a), int32_t: "int32_t", default: "altro");

    printf("a: tipo=%s norma=%.2f\n", t_a, n_a);
    printf("b: tipo=%s norma=%.2f\n", t_b, n_b);
    printf("c: tipo=%s norma=%.2f\n", t_c, n_c);
    printf("p_mut: tipo=%s norma=%.2f\n", t_pm, n_pm);
    printf("p_const: tipo=%s norma=%.2f\n", t_pc, n_pc);
    printf("np: tipo=%s norma=%.2f\n", t_np, n_np);
    printf("Effetti collaterali in _Generic: chiamate=%d (tipo=%s)\n", chiamate, t_check);
    printf("Somma norme: %.2f\n", n_a + n_b + n_c + n_pm + n_pc + n_np);
    return EXIT_SUCCESS;
}

#include <inttypes.h>
#include <limits.h>
#include <stddef.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>

typedef enum stato_pkt : uint8_t {
    PKT_OK = 0,
    PKT_ATTESA = 1,
    PKT_ERRORE = 2,
    PKT_CONTEGGIO = 3
} stato_pkt_t;

static const char *const NOMI_STATO[] = {"OK", "ATTESA", "ERRORE"};

typedef struct pacchetto {
    uint64_t timestamp;
    uint32_t id;
    uint16_t lunghezza;
    uint8_t stato;
    uint8_t flag;
} pacchetto_t;

static_assert(CHAR_BIT == 8, "Richiesti byte da 8 bit");
static_assert(sizeof(pacchetto_t) == 16, "Layout pacchetto_t deve essere di 16 byte");
static_assert(alignof(pacchetto_t) >= alignof(uint64_t));
static_assert(offsetof(pacchetto_t, id) == 8 && offsetof(pacchetto_t, flag) == 15);
static_assert(sizeof(NOMI_STATO) / sizeof(NOMI_STATO[0]) == PKT_CONTEGGIO,
              "NOMI_STATO non allineato a stato_pkt_t");

void scambia_pacchetti(pacchetto_t *a, pacchetto_t *b);
uint64_t peso_pacchetto(const pacchetto_t *p, const uint64_t fattore);

int main(void) {
    char riga[256], extra = '\0';
    int n_in = 0;
    if (fgets(riga, (int)sizeof(riga), stdin) == nullptr ||
        sscanf(riga, "%d %c", &n_in, &extra) != 1 || n_in < 1 || n_in > 32) {
        fprintf(stderr, "Errore: numero pacchetti non valido.\n");
        return EXIT_FAILURE;
    }
    size_t n = (size_t)n_in;
    pacchetto_t *elenco = calloc(n, sizeof(*elenco));
    if (elenco == nullptr) { return EXIT_FAILURE; }
    for (size_t i = 0; i < n; ++i) {
        unsigned long long ts = 0;
        unsigned int id = 0, len = 0, st = 0, fl = 0;
        if (fgets(riga, (int)sizeof(riga), stdin) == nullptr ||
            sscanf(riga, "%llu %u %u %u %u %c", &ts, &id, &len, &st, &fl, &extra) != 5 ||
            len > UINT16_MAX || st >= PKT_CONTEGGIO || fl > UINT8_MAX) {
            free(elenco);
            fprintf(stderr, "Errore: dati pacchetto non validi.\n");
            return EXIT_FAILURE;
        }
        elenco[i] = (pacchetto_t){
            .timestamp = (uint64_t)ts, .id = (uint32_t)id,
            .lunghezza = (uint16_t)len, .stato = (uint8_t)st, .flag = (uint8_t)fl
        };
    }
    for (size_t i = 0; i < n; ++i) {
        for (size_t j = i + 1; j < n; ++j) {
            if (elenco[j].timestamp < elenco[i].timestamp ||
                (elenco[j].timestamp == elenco[i].timestamp && elenco[j].id < elenco[i].id)) {
                scambia_pacchetti(&elenco[i], &elenco[j]);
            }
        }
    }
    auto somma_len = (uint64_t)0;
    auto somma_pond = (uint64_t)0;
    const char *tipo_acc = _Generic(somma_len, uint64_t: "uint64_t", default: "altro");
    printf("Verifiche static_assert: superate (sizeof=%zu)\n", sizeof(pacchetto_t));
    printf("Tipo somma_len (auto): %s\n", tipo_acc);
    for (size_t i = 0; i < n; ++i) {
        auto pond = peso_pacchetto(&elenco[i], 2U);
        somma_len += elenco[i].lunghezza;
        somma_pond += pond;
        printf("#%" PRIu32 " ts=%" PRIu64 " len=%" PRIu16 " stato=%s flag=%" PRIu8 " pond=%" PRIu64 "\n",
               elenco[i].id, elenco[i].timestamp, elenco[i].lunghezza,
               NOMI_STATO[elenco[i].stato], elenco[i].flag, pond);
    }
    printf("Totale lunghezza: %" PRIu64 ", totale ponderato: %" PRIu64 "\n", somma_len, somma_pond);
    free(elenco);
    return EXIT_SUCCESS;
}

void scambia_pacchetti(pacchetto_t *a, pacchetto_t *b) {
    typeof(*a) tmp = *a;
    *a = *b;
    *b = tmp;
}

uint64_t peso_pacchetto(const pacchetto_t *p, const uint64_t fattore) {
    typeof_unqual(fattore) molt = fattore;
    if (p->flag != 0U) {
        ++molt;
    }
    auto ris = (uint64_t)p->lunghezza * molt;
    return ris;
}
